<script setup>
import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import StatusTag from '../components/StatusTag.vue';import { getStudentTask,getTaskRegistration } from '../api/taskApi.js';import { adaptTaskEnvelope,adaptTaskRegistration } from '../adapters/taskAdapter.js';import { getApiErrorMessage } from '../utils/apiFeedback.js'
const route=useRoute();const router=useRouter();const task=ref(null);const result=ref(null);onMounted(async()=>{try{const payload=await getStudentTask(Number(route.params.id));task.value=adaptTaskEnvelope(payload);const registrationId=Number(route.query.registrationId??task.value?.myRegistration?.id);if(Number.isInteger(registrationId)&&registrationId>0){const registration=await getTaskRegistration(registrationId);result.value=adaptTaskRegistration(registration?.registration??registration)}}catch(error){window.alert(getApiErrorMessage(error,'报名结果加载失败'))}});const resultText=computed(()=>['applied','pending_selection'].includes(result.value?.applyStatus)?'已报名，等待指导老师筛选':result.value?.applyStatus==='selected'?'已选中，可参与任务':result.value?.applyStatus==='not_selected'?'未选中':'暂无报名结果');const getTaskTypeText=(value)=>value||'--';function back(){router.push('/student/tasks')}
</script>
<template><main class="page"><div class="content"><template v-if="task&&result"><header><div><p class="eyebrow">S103 · APPLICATION RESULT</p><h1>报名结果</h1><p>{{ task.title }}</p></div><StatusTag :status="result.selected?'confirmed':result.applyStatus==='not_selected'?'rejected':'pending'" :text="resultText" /></header><section class="banner" :class="result.applyStatus"><strong>{{ resultText }}</strong><p v-if="result.isLeader">你已被指定为队长。</p><p v-else-if="result.selected">你已进入任务参与流程，请关注后续安排。</p><p v-else-if="result.applyStatus==='not_selected'">本次报名流程已结束。</p><p v-else>报名不代表最终参与，请等待指导老师处理。</p></section><section class="card"><h2>任务与报名信息</h2><dl><div><dt>任务名称</dt><dd>{{ task.title }}</dd></div><div><dt>任务类型</dt><dd>{{ getTaskTypeText(task.taskType) }}</dd></div><div><dt>指导老师</dt><dd>{{ task.advisorName }}</dd></div><div><dt>报名时间</dt><dd>{{ result.applyTime||'--' }}</dd></div><div><dt>报名状态</dt><dd>{{ result.applyStatus }}</dd></div><div><dt>是否被选中</dt><dd>{{ result.selected?'是':'否' }}</dd></div><div><dt>是否为队长</dt><dd>{{ result.isLeader?'是':'否' }}</dd></div><div><dt>当前后续状态</dt><dd><StatusTag :status="task.status" /></dd></div><div class="wide"><dt>筛选意见 / 未选中原因</dt><dd>{{ result.selectionComment||'无' }}</dd></div></dl></section><div class="actions"><button @click="back">返回我的任务</button><RouterLink v-if="result.selected" :to="`/student/tasks/${task.taskId}/team`">查看团队信息</RouterLink></div></template><section v-else class="card empty">未找到报名结果。<button @click="back">返回</button></section></div></main></template>
<style scoped>.page{min-height:100vh;padding:40px 24px;background:#f3f6fb}.content{width:min(100%,860px);margin:auto}header{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}h1{margin:0}header p{color:#64748b}.eyebrow{margin:0 0 6px;color:#2563eb!important;font-size:12px;font-weight:800;letter-spacing:.12em}.banner{margin-bottom:18px;padding:18px;border-radius:12px;color:#92400e;background:#fef3c7}.banner.selected{color:#166534;background:#dcfce7}.banner.not_selected{color:#b91c1c;background:#fee2e2}.banner p{margin:7px 0 0}.card{padding:22px;border:1px solid #e2e8f0;border-radius:14px;background:#fff}.card h2{margin:0 0 18px}dl{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin:0}.wide{grid-column:1/-1}dt{color:#64748b;font-size:13px}dd{margin:5px 0 0;font-weight:600}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}.actions a,.actions button,.empty button{padding:10px 16px;border:1px solid #cbd5e1;border-radius:9px;color:#2563eb;background:#fff;font:inherit;font-weight:700;text-decoration:none}.empty{text-align:center;color:#64748b}@media(max-width:650px){.page{padding:24px 14px}header{flex-direction:column}dl{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
